using System;
using System.Text.Json;
using Azure;

var err = new ResponseError("TestCode", "TestMessage");
// Try to deserialize  
var json = "{\"code\":\"TestCode\",\"message\":\"TestMessage\"}";
var deserialized = JsonSerializer.Deserialize<ResponseError>(json);
Console.WriteLine($"Code: {deserialized.Code}, Message: {deserialized.Message}");

// Check if we can write the internal element
var t = typeof(ResponseError);
var elemField = t.GetField("_element", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
var elem = (JsonElement)elemField.GetValue(deserialized);
Console.WriteLine($"Element kind: {elem.ValueKind}");
Console.WriteLine($"Element: {elem}");
EOF
